<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pengaturan Hero</title><link rel="stylesheet" href="/assets/admin/admin-shell.css"><style>
.hero-wrap{display:grid;gap:18px;max-width:980px}.hero-upload,.hero-item{background:var(--surface);border:1.5px solid var(--border);border-radius:14px;padding:18px}.hero-upload{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.hero-upload input{max-width:100%}.hero-list{display:grid;gap:10px}.hero-item{display:flex;align-items:center;gap:14px}.hero-item img,.hero-item video{width:180px;height:92px;object-fit:cover;border-radius:10px;background:#0f172a}.hero-item .meta{flex:1}.hero-item button{border:0;border-radius:9px;padding:9px 12px;cursor:pointer}.danger{color:#b91c1c;background:#fee2e2}.note{color:var(--text-3);font-size:13px}.toast{position:fixed;right:20px;bottom:20px;padding:13px 16px;border-radius:11px;background:#172033;color:white;display:none}.toast.bad{background:#a92828}@media(max-width:600px){.hero-item{align-items:flex-start;flex-wrap:wrap}.hero-item img,.hero-item video{width:100%;height:180px}}
</style></head><body><div class="adm-shell">@include('admin.partials.sidebar',['currentPage'=>'trayekwisata_hero','currentModule'=>'trayekwisata'])<main class="adm-main"><div class="adm-content"><div class="adm-page-header"><div><h1 class="adm-page-title">Pengaturan Hero</h1><p class="adm-page-subtitle">Upload media, lalu susun urutan tampil di halaman depan.</p></div></div><div class="hero-wrap"><form class="hero-upload" id="uploadForm"><input id="media" name="file" type="file" accept="image/*,video/mp4" required><button class="adm-btn adm-btn-primary" type="submit">Upload media</button><span class="note">Gambar otomatis WebP. Video wajib MP4 dan harus di bawah 2 MB.</span></form><div class="hero-list" id="list"></div></div></div></main></div><div id="toast" class="toast"></div><script>
const csrf=document.querySelector('meta[name=csrf-token]').content;const list=document.querySelector('#list'),toast=document.querySelector('#toast');let rows=[];
function msg(text,bad=false){toast.textContent=text;toast.className='toast'+(bad?' bad':'');toast.style.display='block';setTimeout(()=>toast.style.display='none',3500)}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'X-CSRF-TOKEN':csrf,'Accept':'application/json'};const r=await fetch(url,opt);const d=await r.json().catch(()=>({error:'Respons server tidak valid.'}));if(!r.ok)throw Error(d.error||'Gagal memproses permintaan.');return d}
let dragged=null;async function saveOrder(){rows=[...document.querySelectorAll('.hero-item')].map(e=>rows.find(r=>r.id===e.dataset.id));try{await api('/admin/api/trayekwisata/hero/reorder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:rows.map(r=>r.id)})});msg('Urutan hero disimpan.')}catch(e){msg(e.message,true)}}function render(){list.innerHTML=rows.map((r,i)=>`<div class="hero-item" draggable="true" data-id="${r.id}">${r.tipe==='video'?`<video src="${r.url}" muted controls></video>`:`<img src="${r.url}" alt="Hero ${i+1}">`}<div class="meta"><b>Hero ${i+1}</b><div class="note">${r.tipe==='video'?'Video MP4':'Gambar WebP'}</div></div><button class="danger" onclick="removeHero('${r.id}')">Hapus</button></div>`).join('');document.querySelectorAll('.hero-item').forEach(x=>{x.addEventListener('dragstart',()=>dragged=x);x.addEventListener('dragover',e=>{e.preventDefault();if(dragged&&dragged!==x){const box=x.getBoundingClientRect();list.insertBefore(dragged,e.clientY<box.top+box.height/2?x:x.nextSibling)}});x.addEventListener('dragend',saveOrder)})}
async function load(){try{rows=await api('/admin/api/trayekwisata/hero');render()}catch(e){msg(e.message,true)}}
document.querySelector('#uploadForm').addEventListener('submit',async e=>{e.preventDefault();const f=document.querySelector('#media').files[0];if(!f)return;if(f.type==='video/mp4'&&f.size>=2097152){msg('Video gagal diupload. Ukuran harus di bawah 2 MB.',true);return}const fd=new FormData();fd.append('file',f);try{const row=await api('/admin/api/trayekwisata/hero/upload',{method:'POST',body:fd});rows.push(row);render();e.target.reset();msg('Media hero berhasil diupload.')}catch(err){msg(err.message,true)}});async function removeHero(id){if(!confirm('Hapus media hero ini?'))return;try{await api('/admin/api/trayekwisata/hero',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});rows=rows.filter(r=>r.id!==id);render();msg('Media hero dihapus.')}catch(e){msg(e.message,true)}}load();
</script></body></html>